import { createWebflowCms, type WebflowCms, type WebflowCmsConfig } from "../core/cms";
import type { WebflowSchema } from "../core/schema";
import { nextCache } from "./cache";

/**
 * Creates the CMS functions wired to the Next.js data cache and draft mode.
 * Usually called from the file generated by `next-webflow typegen`:
 *
 * ```ts
 * export const { getItems, getItemBySlug, getItem } = createWebflow({ schema });
 * ```
 */
export function createWebflow<const S extends WebflowSchema | undefined = undefined>(
  config: WebflowCmsConfig<S> = {},
): WebflowCms<S> {
  // `??`, not a spread default: an explicit `cache: undefined` must not disable caching.
  return createWebflowCms<S>({ ...config, cache: config.cache ?? nextCache });
}

export { nextCache };
